# Cửa sổ trượt theo từng độ lệch 0..L-1 - O(n*L)
from collections import Counter
def solve(s, words):
    L, k = len(words[0]), len(words); need = Counter(words); res = []
    for off in range(L):
        left = off; cnt = Counter(); used = 0
        for r in range(off, len(s) - L + 1, L):
            w = s[r:r+L]
            if w in need:
                cnt[w] += 1; used += 1
                while cnt[w] > need[w]:
                    cnt[s[left:left+L]] -= 1; used -= 1; left += L
                if used == k:
                    res.append(left)
                    cnt[s[left:left+L]] -= 1; used -= 1; left += L
            else:
                cnt.clear(); used = 0; left = r + L
    return sorted(res)
