# Quay lui + bitmask, chọn ô ít lựa chọn nhất trước (MRV)
def solve(b):
    row = [0]*9; col = [0]*9; box = [0]*9; empty = []
    for i in range(9):
        for j in range(9):
            if b[i][j] == '.': empty.append((i, j))
            else:
                m = 1 << int(b[i][j]); row[i] |= m; col[j] |= m; box[i//3*3+j//3] |= m
    def dfs():
        if not empty: return True
        bi, bc = -1, 10
        for idx, (i, j) in enumerate(empty):
            c = bin(~(row[i]|col[j]|box[i//3*3+j//3]) & 0x3FE).count('1')
            if c < bc: bi, bc = idx, c
        i, j = empty[bi]; empty[bi] = empty[-1]; empty.pop(); g = i//3*3+j//3
        free = ~(row[i]|col[j]|box[g]) & 0x3FE
        while free:
            m = free & -free; free ^= m
            row[i] |= m; col[j] |= m; box[g] |= m; b[i][j] = str(m.bit_length()-1)
            if dfs(): return True
            row[i] ^= m; col[j] ^= m; box[g] ^= m
        b[i][j] = '.'; empty.append((i, j)); empty[bi], empty[-1] = empty[-1], empty[bi]
        return False
    dfs(); return b
