# Quay lui với tập cột / đường chéo
def solve(n):
    res = []; q = []; cols = set(); d1 = set(); d2 = set()
    def bt(r):
        if r == n:
            res.append(['.'*c + 'Q' + '.'*(n-c-1) for c in q]); return
        for c in range(n):
            if c in cols or r-c in d1 or r+c in d2: continue
            cols.add(c); d1.add(r-c); d2.add(r+c); q.append(c)
            bt(r+1)
            cols.discard(c); d1.discard(r-c); d2.discard(r+c); q.pop()
    bt(0); return res
