# Quay lui bitmask
def solve(n):
    full = (1 << n) - 1
    def bt(cols, d1, d2):
        if cols == full: return 1
        cnt = 0; free = full & ~(cols | d1 | d2)
        while free:
            b = free & -free; free ^= b
            cnt += bt(cols | b, ((d1 | b) << 1) & full, (d2 | b) >> 1)
        return cnt
    return bt(0, 0, 0)
