# DP có ghi nhớ trên cặp đoạn (i, j, độ dài) - O(n^4)
from functools import lru_cache
def solve(s1, s2):
    n = len(s1)
    @lru_cache(None)
    def f(i, j, L):
        if s1[i:i+L] == s2[j:j+L]: return True
        if sorted(s1[i:i+L]) != sorted(s2[j:j+L]): return False
        for k in range(1, L):
            if f(i, j, k) and f(i+k, j+k, L-k): return True
            if f(i, j+L-k, k) and f(i+k, j, L-k): return True
        return False
    return f(0, 0, n)
