# DFS hậu thứ tự: gain(u) = val + max(0, gain(trái), gain(phải)) - O(n)
from collections import deque
class TreeNode:
    def __init__(s, v): s.val = v; s.left = s.right = None
def build(a):
    if not a or a[0] is None: return None
    root = TreeNode(a[0]); q = deque([root]); i = 1
    while q and i < len(a):
        u = q.popleft()
        if i < len(a) and a[i] is not None: u.left = TreeNode(a[i]); q.append(u.left)
        i += 1
        if i < len(a) and a[i] is not None: u.right = TreeNode(a[i]); q.append(u.right)
        i += 1
    return root
def solve(root):
    best = float('-inf'); gain = {}; st = [(root, False)]
    while st:                       # duyệt lặp để tránh tràn đệ quy
        u, done = st.pop()
        if not u: continue
        if done:
            l = max(0, gain.get(u.left, 0)); r = max(0, gain.get(u.right, 0))
            best = max(best, u.val + l + r); gain[u] = u.val + max(l, r)
        else:
            st += [(u, True), (u.left, False), (u.right, False)]
    return best
(a,) = _read(); _out(solve(build(a)))

