# BFS hai phía - O(N * L * 26)
def solve(begin, end, words):
    ws = set(words)
    if end not in ws: return 0
    front, back = {begin}, {end}; ws.discard(end); steps = 1
    while front and back:
        if len(front) > len(back): front, back = back, front
        nxt = set()
        for w in front:
