# Codec: BFS level-order với "null"; output = cây sau khi serialize rồi deserialize
from collections import deque
class TreeNode:
    def __init__(s, v): s.val = v; s.left = s.right = None
class Codec:
    def serialize(self, root):
        out = []; q = deque([root])
        while q:
            u = q.popleft()
            if u: out.append(str(u.val)); q.append(u.left); q.append(u.right)
            else: out.append('null')
        while out and out[-1] == 'null': out.pop()
        return ','.join(out)
    def deserialize(self, data):
        if not data: return None
        v = data.split(','); root = TreeNode(int(v[0])); q = deque([root]); i = 1
        while q and i < len(v):
            u = q.popleft()
            if i < len(v) and v[i] != 'null': u.left = TreeNode(int(v[i])); q.append(u.left)
            i += 1
            if i < len(v) and v[i] != 'null': u.right = TreeNode(int(v[i])); q.append(u.right)
            i += 1
        return root
