    if n <= 20: return max(missing, replace)
    delete = n - 20; d = delete
    for mod in (0, 1):                      # xoá 1 ký tự ở cụm %3==0, 2 ký tự ở cụm %3==1
        for idx, r in enumerate(runs):
            if r >= 3 and r % 3 == mod and d > mod:
                use = min(d, mod + 1); runs[idx] -= use; d -= use
    for idx, r in enumerate(runs):          # phần xoá còn lại: mỗi 3 ký tự giảm 1 lần thay
        if r >= 3 and d > 0:
