# Danh sách liên kết kép các "bucket" theo số đếm, mỗi bucket giữ tập key - O(1) mọi thao tác
class Node:
    def __init__(s, c): s.cnt = c; s.keys = set(); s.prev = s.next = None
class AllOne:
    def __init__(self):
        self.head = Node(0); self.tail = Node(float('inf'))
        self.head.next = self.tail; self.tail.prev = self.head; self.where = {}
    def _after(self, node, c):
        if node.next.cnt == c: return node.next
        n = Node(c); n.prev, n.next = node, node.next; node.next.prev = n; node.next = n; return n
    def _before(self, node, c):
        if node.prev.cnt == c: return node.prev
        return self._after(node.prev, c)
    def _drop(self, node):
        if not node.keys: node.prev.next = node.next; node.next.prev = node.prev
    def inc(self, k):
        cur = self.where.get(k, self.head); nxt = self._after(cur, cur.cnt + 1)
        nxt.keys.add(k); self.where[k] = nxt
        if cur is not self.head: cur.keys.discard(k); self._drop(cur)
    def dec(self, k):
        cur = self.where[k]
        if cur.cnt == 1: del self.where[k]
        else:
            p = self._before(cur, cur.cnt - 1); p.keys.add(k); self.where[k] = p
        cur.keys.discard(k); self._drop(cur)
    def getMaxKey(self): return next(iter(self.tail.prev.keys)) if self.tail.prev is not self.head else ''
    def getMinKey(self): return next(iter(self.head.next.keys)) if self.head.next is not self.tail else ''
