# Merge sort, đếm cặp nums[i] > 2*nums[j] bằng hai con trỏ trước khi trộn - O(n log n)
def solve(a):
    def sort(lo, hi):
        if hi - lo <= 1: return 0
        mid = (lo + hi) // 2; cnt = sort(lo, mid) + sort(mid, hi); j = mid
        for i in range(lo, mid):
            while j < hi and a[i] > 2 * a[j]: j += 1
            cnt += j - mid
        a[lo:hi] = sorted(a[lo:hi]); return cnt
    return sort(0, len(a))
(a,) = _read(); _out(solve(a))

