# DP: dp[vị trí trên ring] = chi phí nhỏ nhất sau khi gõ key[:i] - O(|key| * |ring|^2) (theo vị trí ký tự)
from collections import defaultdict
def solve(ring, key):
    n = len(ring); pos = defaultdict(list)
    for i, c in enumerate(ring): pos[c].append(i)
    dp = {0: 0}
    for c in key:
        nd = {}
        for j in pos[c]:
            nd[j] = min(v + min(abs(j - i), n - abs(j - i)) for i, v in dp.items()) + 1
        dp = nd
    return min(dp.values())
