# DP 3 chiều dp(l, r, k): k hộp cùng màu boxes[l] đứng trước l - O(n^4)
import sys
from functools import lru_cache
sys.setrecursionlimit(10000)
def solve(b):
    n = len(b)
    @lru_cache(None)
    def f(l, r, k):
        if l > r: return 0
        while l < r and b[l + 1] == b[l]: l += 1; k += 1
        best = (k + 1) ** 2 + f(l + 1, r, 0)
        for m in range(l + 2, r + 1):
            if b[m] == b[l] and b[m - 1] != b[l]:
                best = max(best, f(l + 1, m - 1, 0) + f(m, r, k + 1))
        return best
    return f(0, n - 1, 0)
(b,) = _read(); _out(solve(b))

