# DP trạng thái (số A: 0/1, số L liên tiếp cuối: 0/1/2) - O(n)
def solve(n):
    MOD = 10**9 + 7; dp = [1, 0, 0, 0, 0, 0]   # index = a*3 + l
    for _ in range(n):
        nd = [0] * 6
        for a in range(2):
            for l in range(3):
                v = dp[a * 3 + l]
                if not v: continue
                nd[a * 3] = (nd[a * 3] + v) % MOD                     # P
                if a == 0: nd[3] = (nd[3] + v) % MOD                  # A
                if l < 2: nd[a * 3 + l + 1] = (nd[a * 3 + l + 1] + v) % MOD  # L
        dp = nd
    return sum(dp) % MOD
