# Bao lồi Andrew monotone chain, giữ cả điểm thẳng hàng trên cạnh - O(n log n)
def solve(pts):
    pts = sorted(map(tuple, pts))
    if len(pts) <= 3: return sorted(map(list, set(pts)))
    cross = lambda o, a, b: (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
    def half(ps):
        h = []
        for p in ps:
            while len(h) >= 2 and cross(h[-2], h[-1], p) < 0: h.pop()
            h.append(p)
        return h
    return sorted(map(list, set(half(pts) + half(pts[::-1]))))
(p,) = _read(); _out(solve(p))

