# Duyệt tuần tự với stack tên thẻ; xử lý CDATA, thẻ mở, thẻ đóng
def solve(code):
    st = []; i = 0; n = len(code)
    while i < n:
        if i > 0 and not st: return False            # phải được bọc trong đúng 1 thẻ đóng
        if code.startswith('<![CDATA[', i):
            if not st: return False
            j = code.find(']]>', i + 9)
            if j < 0: return False
            i = j + 3
        elif code.startswith('</', i):
            j = code.find('>', i + 2)
            if j < 0: return False
            name = code[i+2:j]
            if not st or st[-1] != name: return False
            st.pop(); i = j + 1
        elif code[i] == '<':
            j = code.find('>', i + 1)
            if j < 0: return False
            name = code[i+1:j]
            if not (1 <= len(name) <= 9 and name.isalpha() and name.isupper()): return False
            st.append(name); i = j + 1
        else:
            if not st: return False
            i += 1
    return not st and n > 0
(s,) = _read(); _out(solve(s))

