# Min-heap chứa phần tử đầu mỗi danh sách, theo dõi max hiện tại - O(N log k)
import heapq
def solve(lists):
    h = [(l[0], i, 0) for i, l in enumerate(lists)]; heapq.heapify(h)
    hi = max(l[0] for l in lists); best = [h[0][0], hi]
    while True:
        v, i, j = heapq.heappop(h)
        if hi - v < best[1] - best[0]: best = [v, hi]
        if j + 1 == len(lists[i]): return best
        nv = lists[i][j + 1]; hi = max(hi, nv); heapq.heappush(h, (nv, i, j + 1))
