# DP khoảng: dp[i][j]; nếu s[k]==s[i] thì gộp lần in của i vào k - O(n^3)
def solve(s):
    t = []
    for c in s:
        if not t or t[-1] != c: t.append(c)   # bỏ ký tự lặp liên tiếp
    n = len(t); dp = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            best = dp[i + 1][j] + 1
            for k in range(i + 1, j + 1):
                if t[k] == t[i]: best = min(best, dp[i + 1][k - 1] + dp[k][j] if k > i + 1 else dp[k][j])
            dp[i][j] = best
    return dp[0][n - 1]
