# Nhị phân giá trị, đếm số phần tử <= x bằng sum(min(x//i, n)) - O(m log(mn))
def solve(m, n, k):
    lo, hi = 1, m * n
    while lo < hi:
        mid = (lo + hi) // 2
        if sum(min(mid // i, n) for i in range(1, m + 1)) >= k: hi = mid
        else: lo = mid + 1
    return lo
