from fractions import Fraction
def solve(cards):
    def dfs(a):
        if len(a) == 1: return a[0] == 24
        for i in range(len(a)):
            for j in range(len(a)):
                if i == j: continue
                rest = [a[k] for k in range(len(a)) if k != i and k != j]
                x, y = a[i], a[j]
                vals = [x + y, x - y, x * y] + ([x / y] if y else [])
                if any(dfs(rest + [v]) for v in vals): return True
        return False
    return dfs([Fraction(c) for c in cards])
