def solve(grid, hits):
    R, C = len(grid), len(grid[0]); g = [r[:] for r in grid]
    for r, c in hits: g[r][c] -= 1
    TOP = R * C; par = list(range(TOP + 1)); size = [1] * (TOP + 1)
    def find(x):
        while par[x] != x: par[x] = par[par[x]]; x = par[x]
        return x
