        a, b = find(a), find(b)
        if a != b:
            if size[a] < size[b]: a, b = b, a
            par[b] = a; size[a] += size[b]
    def attach(r, c):
        if r == 0: union(r * C + c, TOP)
        for x, y in ((r+1, c), (r-1, c), (r, c+1), (r, c-1)):
            if 0 <= x < R and 0 <= y < C and g[x][y] == 1: union(r * C + c, x * C + y)
