from collections import deque
def solve(blocked, src, tgt):
    B = set(map(tuple, blocked)); limit = len(blocked) * (len(blocked) - 1) // 2; N = 10**6
    def free(s, t):
        q = deque([tuple(s)]); seen = {tuple(s)}
        while q and len(seen) <= limit:
            r, c = q.popleft()
            if [r, c] == t: return True
            for x, y in ((r+1, c), (r-1, c), (r, c+1), (r, c-1)):
                if 0 <= x < N and 0 <= y < N and (x, y) not in B and (x, y) not in seen:
                    seen.add((x, y)); q.append((x, y))
        return len(seen) > limit
