# Nhị phân độ dài + rolling hash kép (kiểm tra lại chuỗi để tránh va chạm) - O(n log n)
# LƯU Ý: nếu có nhiều chuỗi cùng độ dài dài nhất, đề chấp nhận bất kỳ -> checker kiểm tra độ dài + xuất hiện >= 2 lần.
def solve(s):
    n = len(s); a = [ord(c) - 96 for c in s]; MOD = (1 << 61) - 1; B = 131
    def find(L):
        if L == 0: return 0
        h = 0; p = pow(B, L, MOD); seen = {}
        for i in range(n):
            h = (h * B + a[i]) % MOD
            if i >= L: h = (h - a[i - L] * p) % MOD
            if i >= L - 1:
                st = i - L + 1
                if h in seen and any(s[j:j + L] == s[st:st + L] for j in seen[h]): return st
                seen.setdefault(h, []).append(st)
        return -1
