def solve(expr):
    pos = 0
    def union():
        nonlocal pos
        res = concat()
        while pos < len(expr) and expr[pos] == ',': pos += 1; res |= concat()
        return res
    def concat():
        nonlocal pos
        res = {''}
        while pos < len(expr) and expr[pos] not in ',}':
            if expr[pos] == '{': pos += 1; part = union(); pos += 1
            else: part = {expr[pos]}; pos += 1
            res = {a + b for a in res for b in part}
        return res
    return sorted(union())
