        else: i = len(self.st); self.st.append([]); heapq.heappush(self.free, i)
        self.st[i].append(v)
        if len(self.st[i]) == self.cap: heapq.heappop(self.free)
    def popAtStack(self, i):
        if i >= len(self.st) or not self.st[i]: return -1
        v = self.st[i].pop(); heapq.heappush(self.free, i)
        while self.st and not self.st[-1]: self.st.pop()
        return v
    def pop(self): return self.popAtStack(len(self.st) - 1) if self.st else -1
