from collections import Counter
def solve(words, puzzles):
    cnt = Counter()
    for w in words:
        m = 0
        for c in w: m |= 1 << (ord(c) - 97)
        if bin(m).count('1') <= 7: cnt[m] += 1
    res = []
    for p in puzzles:
        first = 1 << (ord(p[0]) - 97); rest = 0
        for c in p[1:]: rest |= 1 << (ord(c) - 97)
        sub = rest; tot = 0
        while True:
