# Tarjan tìm cầu (duyệt lặp) - O(V + E)
def solve(n, conns):
    g = [[] for _ in range(n)]
    for i, (u, v) in enumerate(conns): g[u].append((v, i)); g[v].append((u, i))
    disc = [-1] * n; low = [0] * n; t = 0; res = []
    for s in range(n):
        if disc[s] >= 0: continue
        disc[s] = low[s] = t; t += 1; st = [(s, -1, iter(g[s]))]
        while st:
            u, pe, it = st[-1]; moved = False
            for v, e in it:
                if e == pe: continue
                if disc[v] < 0:
                    disc[v] = low[v] = t; t += 1; st.append((v, e, iter(g[v]))); moved = True; break
                low[u] = min(low[u], disc[v])
            if not moved:
                st.pop()
                if st:
                    p = st[-1][0]; low[p] = min(low[p], low[u])
                    if low[u] > disc[p]: res.append(sorted([p, u]))
    return sorted(res)
