from collections import defaultdict, deque
def topo(nodes, edges):
    indeg = {u: 0 for u in nodes}
    for u in nodes:
        for v in edges[u]: indeg[v] += 1
    q = deque(sorted(u for u in nodes if indeg[u] == 0)); out = []
    while q:
        u = q.popleft(); out.append(u)
        for v in edges[u]:
            indeg[v] -= 1
            if indeg[v] == 0: q.append(v)
    return out if len(out) == len(nodes) else None
def solve(n, m, group, before):
    for i in range(n):
        if group[i] == -1: group[i] = m; m += 1
    ie = defaultdict(list); ge = defaultdict(list)
    for v in range(n):
        for u in before[v]:
            if group[u] == group[v]: ie[u].append(v)
            else: ge[group[u]].append(group[v])
    gorder = topo(list(range(m)), ge)
    if gorder is None: return []
    members = defaultdict(list)
    for i in range(n): members[group[i]].append(i)
    res = []
    for gidx in gorder:
        o = topo(members[gidx], ie)
        if o is None: return []
        res += o
    return res
