# Skiplist nhiều tầng với con trỏ next; tầng ngẫu nhiên p = 1/2 - O(log n) kỳ vọng
import random
random.seed(7)
class Node:
    def __init__(s, v, lv): s.val = v; s.next = [None] * lv
class Skiplist:
    MAX = 16
    def __init__(self): self.head = Node(-1, self.MAX)
    def _path(self, t):
        cur = self.head; path = [None] * self.MAX
        for lv in range(self.MAX - 1, -1, -1):
            while cur.next[lv] and cur.next[lv].val < t: cur = cur.next[lv]
            path[lv] = cur
        return path
    def search(self, t):
        n = self._path(t)[0].next[0]; return bool(n and n.val == t)
    def add(self, x):
        path = self._path(x); lv = 1
        while lv < self.MAX and random.random() < 0.5: lv += 1
        node = Node(x, lv)
        for i in range(lv): node.next[i] = path[i].next[i]; path[i].next[i] = node
    def erase(self, x):
        path = self._path(x); n = path[0].next[0]
        if not n or n.val != x: return False
        for i in range(len(n.next)):
            if path[i].next[i] is n: path[i].next[i] = n.next[i]
        return True
