from collections import deque
def solve(g):
    n = len(g); q = deque([(0, 0, 0, 0)]); seen = {(0, 0, 0)}
    free = lambda r, c: 0 <= r < n and 0 <= c < n and g[r][c] == 0
    while q:
        r, c, d, k = q.popleft()
        if (r, c, d) == (n - 1, n - 2, 0): return k
        nxt = []
        if d == 0:
            if free(r, c + 2): nxt.append((r, c + 1, 0))
            if free(r + 1, c) and free(r + 1, c + 1): nxt += [(r + 1, c, 0), (r, c, 1)]
        else:
            if free(r + 2, c): nxt.append((r + 1, c, 1))
            if free(r, c + 1) and free(r + 1, c + 1): nxt += [(r, c + 1, 1), (r, c, 0)]
        for s in nxt:
            if s not in seen: seen.add(s); q.append((*s, k + 1))
    return -1
