# Quay lui theo "skyline": luôn lấp ô thấp nhất, thử hình vuông lớn trước + cắt nhánh
def solve(n, m):
    if n > m: n, m = m, n
    h = [0] * m; best = [n * m]
    def dfs(cnt):
        if cnt >= best[0]: return
        lo = min(h)
        if lo == n: best[0] = cnt; return
        i = h.index(lo); j = i
        while j < m and h[j] == lo and j - i + 1 <= n - lo: j += 1
        for size in range(j - i, 0, -1):
            for k in range(i, i + size): h[k] += size
            dfs(cnt + 1)
            for k in range(i, i + size): h[k] -= size
    dfs(0); return best[0]
