from collections import deque
def solve(g):
    R, C = len(g), len(g[0])
    for i in range(R):
        for j in range(C):
            if g[i][j] == 'B': box = (i, j)
            elif g[i][j] == 'S': me = (i, j)
            elif g[i][j] == 'T': tgt = (i, j)
    ok = lambda r, c: 0 <= r < R and 0 <= c < C and g[r][c] != '#'
    dq = deque([(0, box, me)]); dist = {(box, me): 0}
    while dq:
        d, b, p = dq.popleft()
        if b == tgt: return d
        if dist[(b, p)] < d: continue
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            np = (p[0] + dr, p[1] + dc)
            if not ok(*np): continue
            if np == b:
                nb = (b[0] + dr, b[1] + dc)
                if ok(*nb) and dist.get((nb, np), 1 << 30) > d + 1:
                    dist[(nb, np)] = d + 1; dq.append((d + 1, nb, np))
            elif dist.get((b, np), 1 << 30) > d:
                dist[(b, np)] = d; dq.appendleft((d, b, np))
