from collections import deque
def solve(grid, catJump, mouseJump):
    R, C = len(grid), len(grid[0]); N = R * C
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 'M': ms = i * C + j
            elif grid[i][j] == 'C': cs = i * C + j
            elif grid[i][j] == 'F': food = i * C + j
    def moves(p, jump):
        r, c = divmod(p, C); res = [p]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            for s in range(1, jump + 1):
                x, y = r + dr * s, c + dc * s
                if not (0 <= x < R and 0 <= y < C) or grid[x][y] == '#': break
                res.append(x * C + y)
        return res
    mm = [moves(p, mouseJump) if grid[p // C][p % C] != '#' else [] for p in range(N)]
    cm = [moves(p, catJump) if grid[p // C][p % C] != '#' else [] for p in range(N)]
    MOUSE, CAT = 1, 2
    res = [[[0, 0] for _ in range(N)] for _ in range(N)]
    deg = [[[len(mm[m]), len(cm[c])] for c in range(N)] for m in range(N)]
    q = deque()
    for p in range(N):
        if grid[p // C][p % C] == '#': continue
        for t in range(2):
            if p != food:
                res[food][p][t] = MOUSE; q.append((food, p, t))
                res[p][food][t] = CAT; q.append((p, food, t))
            res[p][p][t] = CAT; q.append((p, p, t))
    res[food][food] = [CAT, CAT]
    while q:
        m, c, t = q.popleft(); r = res[m][c][t]
        prevs = [(pm, c, 0) for pm in mm[m]] if t == 1 else [(m, pc, 1) for pc in cm[c]]
        for pm, pc, pt in prevs:
            if res[pm][pc][pt]: continue
            if (pt == 0 and r == MOUSE) or (pt == 1 and r == CAT):
                res[pm][pc][pt] = r; q.append((pm, pc, pt))
            else:
                deg[pm][pc][pt] -= 1
                if deg[pm][pc][pt] == 0: res[pm][pc][pt] = r; q.append((pm, pc, pt))
    return res[ms][cs][0] == MOUSE
