def solve(n, paths):
    M1, M2 = (1 << 61) - 1, 10**9 + 7; B = 100003
    def hashes(p, L):
        h1 = h2 = 0; p1 = pow(B, L, M1); p2 = pow(B, L, M2); s = set()
        for i, x in enumerate(p):
            h1 = (h1 * B + x + 1) % M1; h2 = (h2 * B + x + 1) % M2
            if i >= L: h1 = (h1 - (p[i-L] + 1) * p1) % M1; h2 = (h2 - (p[i-L] + 1) * p2) % M2
            if i >= L - 1: s.add((h1, h2))
        return s
    lo, hi = 0, min(map(len, paths))
    while lo < hi:
        m = (lo + hi + 1) // 2; common = hashes(paths[0], m)
        for p in paths[1:]:
            common &= hashes(p, m)
            if not common: break
        if common: lo = m
        else: hi = m - 1
    return lo
