from collections import deque
class TreeNode:
    def __init__(s, v): s.val = v; s.left = s.right = None
def build(a):
    if not a or a[0] is None: return None
    root = TreeNode(a[0]); q = deque([root]); i = 1
    while q and i < len(a):
        u = q.popleft()
        if i < len(a) and a[i] is not None: u.left = TreeNode(a[i]); q.append(u.left)
        i += 1
        if i < len(a) and a[i] is not None: u.right = TreeNode(a[i]); q.append(u.right)
        i += 1
    return root
