def solve(parents, queries):
    n = len(parents); ch = [[] for _ in range(n)]; root = 0
    for i, p in enumerate(parents):
        if p == -1: root = i
        else: ch[p].append(i)
    byn = [[] for _ in range(n)]
    for qi, (node, val) in enumerate(queries): byn[node].append((val, qi))
    B = 18; nxt = [[0, 0]]; cnt = [0]; res = [0] * len(queries)
