# Segment tree lưu (độ dài tiền tố cùng ký tự, hậu tố, tốt nhất) - O((n + q) log n)
def solve(s, qc, qi):
    s = list(s); n = len(s); size = 1
    while size < n: size *= 2
    pre = [0] * (2 * size); suf = [0] * (2 * size); best = [0] * (2 * size); ln = [0] * (2 * size)
    lo = [0] * (2 * size)
    def pull(i):
        l, r = 2 * i, 2 * i + 1; ln[i] = ln[l] + ln[r]
        if not ln[r]: pre[i], suf[i], best[i] = pre[l], suf[l], best[l]; return
        m = lo[r]; join = s[m - 1] == s[m] if ln[l] and ln[r] else False
        pre[i] = pre[l] + (pre[r] if join and pre[l] == ln[l] else 0)
        suf[i] = suf[r] + (suf[l] if join and suf[r] == ln[r] else 0)
        best[i] = max(best[l], best[r], suf[l] + pre[r] if join else 0)
    for i in range(size):
        p = size + i; lo[p] = i
        if i < n: pre[p] = suf[p] = best[p] = ln[p] = 1
    for i in range(size - 1, 0, -1): lo[i] = lo[2 * i]; pull(i)
