class BookMyShow:
    def __init__(self, n, m):
        self.n, self.m = n, m; self.size = 1
        while self.size < n: self.size *= 2
        self.mx = [0] * (2 * self.size); self.sm = [0] * (2 * self.size)
        for i in range(n): self.mx[self.size + i] = self.sm[self.size + i] = m
        for i in range(self.size - 1, 0, -1): self._pull(i)
        self.first = 0
    def _pull(self, i):
        self.mx[i] = max(self.mx[2 * i], self.mx[2 * i + 1]); self.sm[i] = self.sm[2 * i] + self.sm[2 * i + 1]
    def _set(self, row, v):
        p = self.size + row; self.mx[p] = self.sm[p] = v; p //= 2
        while p: self._pull(p); p //= 2
    def _sum(self, r):                       # tổng ghế trống hàng 0..r
        l, r = self.size, self.size + r + 1; s = 0
        while l < r:
            if l & 1: s += self.sm[l]; l += 1
            if r & 1: r -= 1; s += self.sm[r]
            l //= 2; r //= 2
        return s
    def gather(self, k, maxRow):
        if self.mx[1] < k: return []
        i = 1
        while i < self.size: i = 2 * i if self.mx[2 * i] >= k else 2 * i + 1
        row = i - self.size
        if row > maxRow: return []
        free = self.mx[i]; self._set(row, free - k); return [row, self.m - free]
    def scatter(self, k, maxRow):
        if self._sum(maxRow) < k: return False
        r = self.first
        while k:
            f = self.mx[self.size + r]; t = min(f, k); self._set(r, f - t); k -= t
            if f - t == 0: r += 1
        self.first = r; return True
