    for i in range(n): cnt[size + i] = a[i]; ln[size + i] = 1
    for i in range(size - 1, 0, -1): cnt[i] = cnt[2*i] + cnt[2*i+1]; ln[i] = ln[2*i] + ln[2*i+1]
    def apply(i): cnt[i] = ln[i] - cnt[i]; lz[i] = not lz[i]
    def flip(i, lo, hi, l, r):
        if r < lo or hi < l: return
        if l <= lo and hi <= r: apply(i); return
        if lz[i]: apply(2*i); apply(2*i+1); lz[i] = False
        m = (lo + hi) // 2; flip(2*i, lo, m, l, r); flip(2*i+1, m + 1, hi, l, r)
        cnt[i] = cnt[2*i] + cnt[2*i+1]
    total = sum(b); res = []
    for t, x, y in queries:
        if t == 1: flip(1, 0, size - 1, x, y)
        elif t == 2: total += x * cnt[1]
