        if i < len(low) and low[i] == x:
            low.pop(i); s -= x
            if high: y = high.pop(0); bisect.insort(low, y); s += y
        else: high.pop(bisect.bisect_left(high, x))
    for i, x in enumerate(b):
        add(x)
        if i > dist: remove(b[i - dist - 1])
        if i >= k - 1 and len(low) == k: best = min(best, s)
    return a[0] + best
