    vals = sorted(set(a)); m = len(vals); b1 = [0] * (m + 1); b2 = [0] * (m + 1)
    def add(b, i):
        while i <= m: b[i] += 1; i += i & -i
    def q(b, i):
        s = 0
        while i > 0: s += b[i]; i -= i & -i
        return s
    A = [a[0]]; B = [a[1]]; add(b1, bisect.bisect_left(vals, a[0]) + 1); add(b2, bisect.bisect_left(vals, a[1]) + 1)
    for x in a[2:]:
        r = bisect.bisect_left(vals, x) + 1
        g1 = len(A) - q(b1, r); g2 = len(B) - q(b2, r)
        if g1 > g2 or (g1 == g2 and len(A) <= len(B)): A.append(x); add(b1, r)
        else: B.append(x); add(b2, r)
    return A + B
