def solve(a, k):
    NEG = float('-inf'); best = [0] + [NEG] * k; cur = [NEG] * (k + 1)
    for x in a:
        for j in range(k, 0, -1):
            w = (k - j + 1) * (1 if j % 2 else -1)
            cur[j] = max(cur[j], best[j - 1]) + w * x
            best[j] = max(best[j], cur[j])
