    if mc >= k - c: return max(c - 1, 0) + 2 * (k - c)
    pos = [i for i, x in enumerate(a) if x]; need = k - mc; P = [0]
    for p in pos: P.append(P[-1] + p)
    best = float('inf')
    for l in range(len(pos) - need + 1):
        r = l + need - 1; m = (l + r) // 2; med = pos[m]
        cost = med * (m - l) - (P[m] - P[l]) + (P[r + 1] - P[m + 1]) - med * (r - m)
        best = min(best, cost)
