import sys
from functools import lru_cache
sys.setrecursionlimit(100000)
def solve(nums, andv):
    n, m = len(nums), len(andv); INF = float('inf')
    @lru_cache(None)
    def dp(i, j, cur):
        if j == m: return 0 if i == n else INF
        if i == n: return INF
        c = cur & nums[i]
        if c < andv[j]: return INF                      # AND chỉ giảm, không thể đạt nữa
        best = dp(i + 1, j, c)
        if c == andv[j]: best = min(best, nums[i] + dp(i + 1, j + 1, -1))
        return best
    r = dp(0, 0, -1); return r if r < INF else -1
