import heapq
def solve(n, edges):
    g = [[] for _ in range(n)]
    for u, v, w in edges: g[u].append((v, w)); g[v].append((u, w))
    def dij(s):
        d = [float('inf')] * n; d[s] = 0; pq = [(0, s)]
        while pq:
            du, u = heapq.heappop(pq)
            if du > d[u]: continue
            for v, w in g[u]:
                if du + w < d[v]: d[v] = du + w; heapq.heappush(pq, (d[v], v))
        return d
    a, b = dij(0), dij(n - 1); D = a[n - 1]
    if D == float('inf'): return [False] * len(edges)
    return [a[u] + w + b[v] == D or a[v] + w + b[u] == D for u, v, w in edges]
