def solve(nums):
    n = len(nums); full = (1 << n) - 1; INF = float('inf')
    dp = [[INF] * n for _ in range(1 << n)]
    for last in range(n): dp[full][last] = abs(last - nums[0])
    for mask in range(full - 1, 0, -1):
        if not mask & 1: continue
        for last in range(n):
            if not mask >> last & 1: continue
            best = INF
            for nx in range(n):
                if not mask >> nx & 1:
                    v = abs(last - nums[nx]) + dp[mask | 1 << nx][nx]
                    if v < best: best = v
            dp[mask][last] = best
    perm = [0]; mask = 1; last = 0
    while mask != full:
        target = dp[mask][last]
        for nx in range(n):
            if not mask >> nx & 1 and abs(last - nums[nx]) + dp[mask | 1 << nx][nx] == target:
                perm.append(nx); mask |= 1 << nx; last = nx; break
