# Fenwick max tiền tố của khoảng trống kết thúc tại vật cản + bisect tìm vật cản trước x
import bisect
def solve(queries):
    M = min(5 * 10**4, 3 * len(queries)) + 1
    M = max(M, max(q[1] for q in queries) + 1)
    obs = sorted({0} | {q[1] for q in queries if q[0] == 1}); bit = [0] * (M + 2)
    def upd(i, v):
        i += 1
        while i <= M + 1: bit[i] = max(bit[i], v); i += i & -i
    def qry(i):
        i += 1; r = 0
        while i > 0: r = max(r, bit[i]); i -= i & -i
        return r
    for a, b in zip(obs, obs[1:]): upd(b, b - a)
    res = []
    for q in reversed(queries):
        if q[0] == 1:
            x = q[1]; i = bisect.bisect_left(obs, x); prev = obs[i - 1]
            if i + 1 < len(obs): upd(obs[i + 1], obs[i + 1] - prev)
            obs.pop(i)
        else:
            x, sz = q[1], q[2]; i = bisect.bisect_right(obs, x) - 1
            res.append(max(qry(obs[i]), x - obs[i]) >= sz)
    return res[::-1]
