# Segment tree 4 trạng thái (có lấy phần tử đầu/cuối đoạn hay không) - O((n + q) log n)
def solve(nums, queries):
    MOD = 10**9 + 7; n = len(nums); size = 1
    while size < n: size *= 2
    NEG = float('-inf'); t = [None] * (2 * size)       # t[i] = [nn, ny, yn, yy] (đầu, cuối được lấy?)
    def leaf(v): return [0, NEG, NEG, v]              # không lấy / lấy phần tử đơn
    def merge(A, B):
        if A is None: return B
        if B is None: return A
        r = [NEG] * 4
        for s in range(2):
            for e in range(2):
                best = NEG
                for m1 in range(2):
                    for m2 in range(2):
                        if m1 and m2: continue
                        v = A[s * 2 + m1] + B[m2 * 2 + e]
                        if v > best: best = v
                r[s * 2 + e] = best
        return r
    for i in range(n): t[size + i] = leaf(nums[i])
    for i in range(size - 1, 0, -1): t[i] = merge(t[2 * i], t[2 * i + 1])
    res = 0
    for p, x in queries:
        i = size + p; t[i] = leaf(x); i //= 2
        while i: t[i] = merge(t[2 * i], t[2 * i + 1]); i //= 2
        res = (res + max(0, max(t[1]))) % MOD
    return res
