def solve(a, k, x):
    cnt = Counter(); top = []; rest = []; s = 0; res = []
    def remove(key):
        nonlocal s
        i = bisect.bisect_left(top, key)
        if i < len(top) and top[i] == key: top.pop(i); s -= key[0] * key[1]
        else: rest.pop(bisect.bisect_left(rest, key))
    def insert(key):
        nonlocal s
        bisect.insort(top, key); s += key[0] * key[1]
    def balance():
        nonlocal s
        while len(top) > x: key = top.pop(0); s -= key[0] * key[1]; bisect.insort(rest, key)
        while len(top) < x and rest: key = rest.pop(); bisect.insort(top, key); s += key[0] * key[1]
        while top and rest and rest[-1] > top[0]:
            a1 = rest.pop(); b1 = top.pop(0); s += a1[0] * a1[1] - b1[0] * b1[1]
            bisect.insort(top, a1); bisect.insort(rest, b1)
