def digit_exp(d):
    return [(d == 2) + 2 * (d == 4) + (d == 6) + 3 * (d == 8), (d == 3) + (d == 6) + 2 * (d == 9), int(d == 5), int(d == 7)]
def min_digits(need):                                 # bộ chữ số ít nhất, sắp tăng (nhỏ nhất)
    a, b, c, d = [max(0, x) for x in need]; res = [7] * d + [5] * c + [9] * (b // 2) + [8] * (a // 3)
    b %= 2; a %= 3
    if a == 2 and b == 1: res += [2, 6]
    elif a == 1 and b == 1: res += [6]
    elif a == 2: res += [4]
    elif a == 1: res += [2]
    elif b == 1: res += [3]
    return sorted(res)
def solve(num, t):
    e, rest = factor(t)
    if rest > 1: return '-1'
    n = len(num); ds = [int(c) for c in num]
    zero = ds.index(0) if 0 in ds else n
    pref = [e[:]]                                    # pref[i] = nhu cầu còn lại sau i chữ số đầu
    for i in range(min(zero, n)):
        x = digit_exp(ds[i]); pref.append([p - q for p, q in zip(pref[-1], x)])
    if zero == n and all(v <= 0 for v in pref[n]): return num
    for i in range(min(zero, n - 1), -1, -1):
        for d in range(ds[i] + 1, 10):
            need = [p - q for p, q in zip(pref[i], digit_exp(d))]; md = min_digits(need); L = n - i - 1
