def solve(a):
    n = len(a); base = 0; nb = []
    for i in range(n - 1):
        if a[i] != -1 and a[i + 1] != -1: base = max(base, abs(a[i] - a[i + 1]))
    for i in range(n):
        if a[i] != -1 and ((i > 0 and a[i - 1] == -1) or (i + 1 < n and a[i + 1] == -1)): nb.append(a[i])
    if not nb: return base
    segs = []; i = 0
    while i < n:
        if a[i] == -1:
            j = i
            while j < n and a[j] == -1: j += 1
            segs.append((a[i - 1] if i > 0 else None, a[j] if j < n else None, j - i)); i = j
        else: i += 1
    mn, mx = min(nb), max(nb)
    def ok(d):
        x, y = mn + d, mx - d
        for l, r, L in segs:
            vals = [v for v in (l, r) if v is not None]
            if not vals: continue
            fit = lambda v: all(abs(u - v) <= d for u in vals)
            if fit(x) or fit(y): continue
            if len(vals) == 2 and L >= 2 and abs(x - y) <= d and \
               ((abs(l - x) <= d and abs(r - y) <= d) or (abs(l - y) <= d and abs(r - x) <= d)): continue
            return False
        return True
    lo, hi = base, max(base, mx - mn)
    while lo < hi:
        m = (lo + hi) // 2
        if ok(m): hi = m
        else: lo = m + 1
    return lo
