# DSU trên giá trị 1..threshold: nối x với mọi bội của x (<= threshold); số > threshold đứng riêng - O(T log T)
def solve(a, th):
    par = list(range(th + 1))
    def find(x):
        while par[x] != x: par[x] = par[par[x]]; x = par[x]
        return x
    big = 0; small = []
    for x in a:
        if x > th: big += 1
        else: small.append(x)
    for x in small:
        for m in range(2 * x, th + 1, x): par[find(m)] = find(x)
    return big + len({find(x) for x in small})
