import bisect
from collections import defaultdict
def solve(xs, ys):
    ycoord = sorted(set(ys)); m = len(ycoord); bit = [0] * (m + 1)
    def add(i):
        i += 1
        while i <= m: bit[i] += 1; i += i & -i
    def q(i):
        i += 1; s = 0
        while i > 0: s += bit[i]; i -= i & -i
        return s
    cols = defaultdict(list)
    for x, y in zip(xs, ys): cols[x].append(bisect.bisect_left(ycoord, y))
    last = {}; best = -1
    for x in sorted(cols):
        c = sorted(cols[x])
        for y1, y2 in zip(c, c[1:]):
            cnt = q(y2) - q(y1 - 1)
            if (y1, y2) in last:
                px, pc = last[(y1, y2)]
                if pc == cnt: best = max(best, (x - px) * (ycoord[y2] - ycoord[y1]))
        for y in c: add(y)
        for y1, y2 in zip(c, c[1:]): last[(y1, y2)] = (x, q(y2) - q(y1 - 1))
    return best
