from collections import defaultdict
def solve(a):
    n = len(a); size = 1
    while size < n: size *= 2
    NEG = float('-inf'); t = [None] * (2 * size)
    def leaf(v): return (v, v, v, v)                    # tổng, tiền tố max, hậu tố max, tốt nhất
    def merge(A, B):
        if A is None: return B
