        while p: t[p] = merge(t[2 * p], t[2 * p + 1]); p //= 2
    for i in range(n): t[size + i] = leaf(a[i])
    for i in range(size - 1, 0, -1): t[i] = merge(t[2 * i], t[2 * i + 1])
    best = t[1][3]; pos = defaultdict(list)
    for i, x in enumerate(a): pos[x].append(i)
