from collections import deque
def solve(a, k):
    n = len(a); dq = deque(); cost = 0; r = n - 1; res = 0
    # dq chứa các chỉ số đầu khối theo thứ tự tăng; khối của dq[t] kéo tới dq[t+1]-1 (hoặc r)
