        no = [0] + [NEG] * budget; yes = [0] + [NEG] * budget
        for v in ch[u]: no = merge(no, f[v][0]); yes = merge(yes, f[v][1])
        res = []
        for pb in range(2):
            cost = present[u - 1] // 2 if pb else present[u - 1]; gain = future[u - 1] - cost
