import bisect
def solve(nums, queries):
    n = len(nums); M = 10**5 + 1; isp = bytearray([1]) * (M + 1); isp[0] = isp[1] = 0
    for i in range(2, int(M ** 0.5) + 1):
        if isp[i]: isp[i * i::i] = bytearray(len(isp[i * i::i]))
    size = 1
    while size < n + 1: size *= 2
    mx = [0] * (2 * size); lz = [0] * (2 * size)
    def add(l, r, v, i=1, lo=0, hi=None):
        if hi is None: hi = size - 1
        if r < lo or hi < l or l > r: return
        if l <= lo and hi <= r: mx[i] += v; lz[i] += v; return
        m = (lo + hi) // 2; add(l, r, v, 2 * i, lo, m); add(l, r, v, 2 * i + 1, m + 1, hi)
        mx[i] = max(mx[2 * i], mx[2 * i + 1]) + lz[i]
    def qmax(l, r, i=1, lo=0, hi=None):
        if hi is None: hi = size - 1
        if r < lo or hi < l: return float('-inf')
        if l <= lo and hi <= r: return mx[i]
        m = (lo + hi) // 2; return max(qmax(l, r, 2 * i, lo, m), qmax(l, r, 2 * i + 1, m + 1, hi)) + lz[i]
    pos = {}
    def span(p, sign):
        ps = pos[p]
        if len(ps) >= 2: add(ps[0] + 1, ps[-1], sign)
    for i, x in enumerate(nums):
        if isp[x]: pos.setdefault(x, []).append(i)
    for p in pos: span(p, 1)
    a = nums[:]; res = []
    for idx, val in queries:
        old = a[idx]
        if isp[old]:
            span(old, -1); pos[old].pop(bisect.bisect_left(pos[old], idx))
            if pos[old]: span(old, 1)
            else: del pos[old]
        a[idx] = val
        if isp[val]:
            if val in pos: span(val, -1)
            bisect.insort(pos.setdefault(val, []), idx); span(val, 1)
        res.append(len(pos) + (qmax(1, n - 1) if n > 1 else 0))
    return res
