def solve(n, edges, queries):
    g = [[] for _ in range(n)]
    for a, b, w in edges: g[a].append((b, w)); g[b].append((a, w))
    LOG = max(1, n.bit_length()); up = [[0] * n for _ in range(LOG)]; dep = [0] * n; dist = [0] * n
    order = [0]; seen = [False] * n; seen[0] = True
    for u in order:
        for v, w in g[u]:
            if not seen[v]: seen[v] = True; up[0][v] = u; dep[v] = dep[u] + 1; dist[v] = dist[u] + w; order.append(v)
    for j in range(1, LOG): up[j] = [up[j - 1][up[j - 1][v]] for v in range(n)]
    def lca(a, b):
        if dep[a] < dep[b]: a, b = b, a
        d = dep[a] - dep[b]
        for j in range(LOG):
            if d >> j & 1: a = up[j][a]
        if a == b: return a
        for j in range(LOG - 1, -1, -1):
            if up[j][a] != up[j][b]: a, b = up[j][a], up[j][b]
