        if 2 * (dist[u] - dist[l]) >= total:        # nằm trên nhánh u -> l: nút sâu nhất ... lên cao nhất với 2*(dist[u]-dist[x]) < total
            x = u
            for j in range(LOG - 1, -1, -1):
                y = up[j][x]
                if dep[y] >= dep[l] and 2 * (dist[u] - dist[y]) < total: x = y
            res.append(x if 2 * (dist[u] - dist[x]) >= total else up[0][x])
        else:                                        # trên nhánh l -> v: nút nông nhất x với dist(u,x) >= total/2
            x = v
