import bisect
def solve(a, queries):
    n = len(a); start = [0] * n; P = [0] * (n + 1); heads = [0]
    for i in range(1, n):
        start[i] = start[i - 1] if a[i - 1] <= a[i] else i
        if start[i] == i: heads.append(i)
    for i in range(n): P[i + 1] = P[i] + (i - start[i] + 1)
    res = []
    for l, r in queries:
        p = heads[bisect.bisect_right(heads, l)] if bisect.bisect_right(heads, l) < len(heads) else n   # đầu run kế tiếp sau l
        p = min(p, r + 1)
        m = p - l                                  # các phần tử trong run chứa l: đóng góp 1..m
        res.append(m * (m + 1) // 2 + P[r + 1] - P[p])
    return res
a, q = _read(); _out(solve(a, q))

