# Digit DP trả về (số lượng, tổng waviness): trạng thái (vị trí, chữ số áp chót, chữ số cuối, chặn, đã bắt đầu, độ dài >= 2)
from functools import lru_cache
def total(N):
    if N < 100: return 0
    s = str(N)
    @lru_cache(None)
    def dp(i, p2, p1, tight, started):            # p2, p1 = -1 nếu chưa có
        if i == len(s): return (1, 0)
        lim = int(s[i]) if tight else 9; cnt = sm = 0
        for d in range(lim + 1):
            nt = tight and d == lim
            if not started and d == 0: c, w = dp(i + 1, -1, -1, nt, False)
            else:
                add = 1 if p2 >= 0 and ((p1 > p2 and p1 > d) or (p1 < p2 and p1 < d)) else 0
                c, w = dp(i + 1, p1, d, nt, True); w += add * c
            cnt += c; sm += w
        return (cnt, sm)
    return dp(0, -1, -1, True, False)[1]
a, b = _read(); _out(total(b) - total(a - 1))

