# Phần còn lại T phải có OR != OR tổng; đếm T có OR = tổng bằng bao hàm-loại trừ trên mask con (SOS DP) - O(B 2^B + n)
def solve(a):
    MOD = 10**9 + 7; tot = 0
    for x in a: tot |= x
    bits = [b for b in range(21) if tot >> b & 1]; B = len(bits)
    f = [0] * (1 << B)
    for x in a:
        m = 0
        for i, b in enumerate(bits):
            if x >> b & 1: m |= 1 << i
        f[m] += 1
    for i in range(B):                              # f[mask] = số phần tử có mask con của mask
        for m in range(1 << B):
            if m >> i & 1: f[m] += f[m ^ (1 << i)]
    full = (1 << B) - 1; eq = 0
    for m in range(1 << B):
        sgn = -1 if (B - bin(m).count('1')) % 2 else 1
        eq += sgn * pow(2, f[m], MOD)
    return (pow(2, len(a), MOD) - eq) % MOD
(a,) = _read(); _out(solve(a))

