# Cần cùng số dư mod k trên đoạn (tiền tố đếm vị trí đổi số dư); số bước = sum |q_i - trung vị| với q = x // k
# Mỗi truy vấn sắp đoạn - O(len log len) (bản tối ưu dùng cây phân đoạn bền vững / wavelet tree)
def solve(a, k, queries):
    n = len(a); brk = [0] * n
    for i in range(1, n): brk[i] = brk[i - 1] + (a[i] % k != a[i - 1] % k)
    res = []
    for l, r in queries:
        if brk[r] - brk[l]: res.append(-1); continue
        q = sorted(x // k for x in a[l:r + 1]); m = q[len(q) // 2]
        res.append(sum(abs(v - m) for v in q))
    return res
a, k, q = _read(); _out(solve(a, k, q))

