# Cửa sổ trượt + Fenwick trên giá trị nén: bỏ trái trừ số phần tử nhỏ hơn nó, thêm phải cộng số lớn hơn nó - O(n log n)
import bisect
def solve(a, k):
    vals = sorted(set(a)); m = len(vals); bit = [0] * (m + 1)
    rk = [bisect.bisect_left(vals, x) + 1 for x in a]
    def add(i, v):
        while i <= m: bit[i] += v; i += i & -i
    def q(i):
        s = 0
        while i > 0: s += bit[i]; i -= i & -i
        return s
    inv = 0; best = None; size = 0
    for i, r in enumerate(rk):
        inv += size - q(r); add(r, 1); size += 1
        if i >= k:
            x = rk[i - k]; add(x, -1); size -= 1; inv -= q(x - 1)
        if i >= k - 1: best = inv if best is None else min(best, inv)
    return best
a, k = _read(); _out(solve(a, k))

