# Rerooting: down[u] = w[u] + sum max(0, down[con]); full[u] = down[u] + max(0, full[cha] - max(0, down[u])) - O(n)
def solve(n, edges, good):
    g = [[] for _ in range(n)]
    for a, b in edges: g[a].append(b); g[b].append(a)
    w = [1 if x else -1 for x in good]
    order = [0]; par = [-1] * n; seen = [False] * n; seen[0] = True
    for u in order:
        for v in g[u]:
            if not seen[v]: seen[v] = True; par[v] = u; order.append(v)
    down = w[:]
    for u in reversed(order):
        if par[u] >= 0: down[par[u]] += max(0, down[u])
    full = down[:]
    for u in order[1:]: full[u] = down[u] + max(0, full[par[u]] - max(0, down[u]))
    return full
n, e, gd = _read(); _out(solve(n, e, gd))

