# Số lần xoá = số cặp kề bằng nhau trong [l, r]; Fenwick trên eq[i] = (s[i] == s[i+1]), lật ký tự sửa 2 vị trí - O((n + q) log n)
def solve(s, queries):
    s = list(s); n = len(s); bit = [0] * (n + 1); eq = [0] * n
    def add(i, v):
        i += 1
        while i <= n: bit[i] += v; i += i & -i
    def q(i):
        i += 1; r = 0
        while i > 0: r += bit[i]; i -= i & -i
        return r
    def setq(i):
        if 0 <= i < n - 1:
            v = 1 if s[i] == s[i + 1] else 0
            if v != eq[i]: add(i, v - eq[i]); eq[i] = v
    for i in range(n - 1): setq(i)
    res = []
    for qu in queries:
        if qu[0] == 1:
            j = qu[1]; s[j] = 'A' if s[j] == 'B' else 'B'; setq(j - 1); setq(j)
        else:
            l, r = qu[1], qu[2]; res.append(q(r - 1) - q(l - 1) if r > l else 0)
    return res
s, q = _read(); _out(solve(s, q))

