# Dãy còn lại luôn là cấp số cộng (đầu, bước, số lượng); mỗi thao tác giữ vị trí chẵn tính từ đầu tương ứng - O(log n)
def solve(n):
    first, step, cnt, left = 1, 1, n, True
    while cnt > 1:
        if not left and cnt % 2 == 0: first += step        # từ phải, số lượng chẵn -> phần tử đầu bị xoá
        step *= 2; cnt = (cnt + 1) // 2; left = not left
    return first
(n,) = _read(); _out(solve(n))

