# Vị trí xấu (nums[i] == forbidden[i]) nhóm theo giá trị; đổi chéo hai vị trí xấu khác giá trị sửa cả hai.
# Khả thi <=> mỗi giá trị v: số lần xuất hiện trong nums <= số vị trí có forbidden != v. Đáp án max(ceil(B/2), max b_v) - O(n)
from collections import Counter
def solve(nums, forb):
    n = len(nums); cn = Counter(nums); cf = Counter(forb)
    for v, c in cn.items():
        if c > n - cf[v]: return -1
    bad = Counter(x for x, f in zip(nums, forb) if x == f); B = sum(bad.values())
    if B == 0: return 0
    return max((B + 1) // 2, max(bad.values()))
a, f = _read(); _out(solve(a, f))

