# Mỗi cạnh (cha, con) góp sum_g cnt_g(cây con) * (tổng_g - cnt_g(cây con)); nhóm <= 20 nên mảng đếm nhỏ - O(n G)
def solve(n, edges, group):
    g = [[] for _ in range(n)]
    for a, b in edges: g[a].append(b); g[b].append(a)
    G = max(group) + 1; total = [0] * G
    for x in group: total[x] += 1
    order = [0]; par = [-1] * n; seen = [False] * n; seen[0] = True
    for u in order:
        for v in g[u]:
            if not seen[v]: seen[v] = True; par[v] = u; order.append(v)
    cnt = [None] * n; res = 0
    for u in reversed(order):
        c = [0] * G; c[group[u]] = 1
        for v in g[u]:
            if v != par[u]:
                cv = cnt[v]
                for t in range(G): c[t] += cv[t]
                cnt[v] = None
        cnt[u] = c
        if par[u] >= 0: res += sum(c[t] * (total[t] - c[t]) for t in range(G))
    return res
n, e, gr = _read(); _out(solve(n, e, gr))
